// ============================================================================
// CONCIERGE CODE NODE  ·  v7.5.3  ·  + client-facing buffered ETA line (v0.4)
// ============================================================================
// v7.5.3: renders the "tell client" buffered line on c eta cards. Reads new
// fields from dispatch v0.4.0 (client_eta_minutes, client_arrival_label,
// buffer_minutes). Backward-compatible: if dispatch hasn't been updated yet,
// the new line is skipped silently.
// ============================================================================
// v7.5.2: state-staged prompts (kills iOS stickiness)
// ============================================================================
// v7.5.2: replaces force_reply on the 3 reply-keyboard prompt buttons
// (+ add / - sub / 💵 paid) with server-side state-staged prompts keyed by
// chat_id. The bot sends a plain message (no force_reply, no reply context)
// when a prompt button is tapped, records the staged prompt in
// data.ui_prompts[chatId], and on the user's NEXT message in that chat:
//   - if it's a valid answer (number for add/sub, name [amount] for paid)
//     → translate to synthetic command, clear staged prompt, fall through
//   - if it starts with 'c ' (any other command)
//     → cancel the staged prompt, let the command run normally
//   - if it's stale (>5 min)
//     → auto-expire silently, let the message route normally
//
// Fixes the iOS reply-context stickiness bug where typing a follow-up
// command after answering a prompt was silently swallowed.
//
// v7.6.0 features (c eta, dispatch integration) unchanged.
// v7.5.0 features (reply keyboard, button taps) unchanged except for the
// 3 prompt buttons which now use the new staged-prompt mechanism.
//
// Same single Code node. Paste and save.
// ============================================================================

var data = $getWorkflowStaticData('global');

// ===== 1. BOOTSTRAP ==========================================================

if (!data.initialized) {
  data.wallet = { cash: 0, pay: 0, updated_at: null };
  data.inventory = { c:0, '50c':0, p:0, '50p':0, b:0, '50k':0, k:0, m:0, s:0 };
  data.orders = [];
  data.voids = [];
  data.clients = {};
  data.front = {};
  data.log = [];
  data.pending = {};
  data.pending_edits = {};
  data.pending_actions = {};
  data.front_prompts = {};
  data.undo_buffer = null;
  data.next_order_id = 1;
  data.next_action_id = 1;
  data.claude_disabled = false;
  data.initialized = true;
}

if (!data.pending) { data.pending = {}; }
if (!data.pending_edits) { data.pending_edits = {}; }
if (!data.pending_actions) { data.pending_actions = {}; }
if (!data.front_prompts) { data.front_prompts = {}; }
if (!data.voids) { data.voids = []; }
if (!data.clients) { data.clients = {}; }
if (!data.front) { data.front = {}; }
if (!data.next_order_id) { data.next_order_id = 1; }
if (!data.next_action_id) { data.next_action_id = 1; }
if (data.wallet && (data.wallet.pay === undefined || data.wallet.pay === null)) { data.wallet.pay = 0; }
if (data.wallet && data.wallet.credit_out !== undefined) { delete data.wallet.credit_out; }
if (data.claude_disabled === undefined) { data.claude_disabled = false; }
if (!data.ui_prompts) { data.ui_prompts = {}; }

// ===== 1b. DISPATCH INTEGRATION CONSTANTS (v7.6.0) ===========================
// URL and shared secret for the concierge-dispatch ETA webhook.

var DISPATCH_ETA_URL    = $env.DISPATCH_ETA_URL;
var DISPATCH_SECRET     = $env.DISPATCH_SECRET;
var DISPATCH_TIMEOUT_MS = 8000;

// Capture the HTTP helper at top level so async handlers can use it.
var httpRequest = this.helpers.httpRequest.bind(this.helpers);

// ===== 1c. STAGED PROMPT CONSTANTS (v7.5.2) ==================================
// How long a staged prompt stays alive before it auto-expires. 5 minutes is
// long enough to type a reply after a real-world interruption but short
// enough that an abandoned prompt doesn't shadow a future message hours later.

var UI_PROMPT_TTL_SEC = 300;

// ===== 2. PARSE INPUT ========================================================

var msg = $json.message;
var chatId = msg.chat.id;
var userId = msg.from.id;
var rawText = msg.text || '';
var text = rawText.toLowerCase().trim();
var nowTs = Math.floor(Date.now() / 1000);

var validProducts = ['c','50c','p','50p','b','50k','k','m','s'];

// Operator command words (prefix-free). Used by the gate-free router to tell a
// command from order intake. Each maps to an existing 'c xxx' dispatch key.
var COMMAND_HEADS = ['wallet','jobs','front','inv','client','clients','summary','backup','undo','cancel','void','edit','eta','kb','keyboard','cmd','commands','new','purge'];

// ===== 3. HELPERS ============================================================

function pushLog(action, details) {
  data.log.push({ ts: nowTs, by: userId, action: action, details: details });
  if (data.log.length > 500) { data.log = data.log.slice(data.log.length - 500); }
}

function montrealDateStr(ts) {
  var d = new Date(ts * 1000);
  var fmt = new Intl.DateTimeFormat('en-CA', { timeZone: 'America/Toronto', year: 'numeric', month: '2-digit', day: '2-digit' });
  return fmt.format(d);
}

function montrealDatePretty(dateStr) {
  var parts = dateStr.split('-');
  var months = ['JAN','FEB','MAR','APR','MAY','JUN','JUL','AUG','SEP','OCT','NOV','DEC'];
  var m = parseInt(parts[1], 10) - 1;
  var dn = parseInt(parts[2], 10);
  return months[m] + ' ' + dn + ', ' + parts[0];
}

function fmtInv() {
  var inv = data.inventory;
  var lines = [];
  lines.push('INVENTORY');
  lines.push('────────────────');
  lines.push('c ' + inv.c + ' · 50c ' + inv['50c']);
  lines.push('p ' + inv.p + ' · 50p ' + inv['50p']);
  lines.push('k ' + inv.k + ' · 50k ' + inv['50k']);
  lines.push('b ' + inv.b + ' · m ' + inv.m + ' · s ' + inv.s);
  return lines.join('\n');
}

function totalFrontOut() {
  var sum = 0;
  var n;
  for (n in data.front) {
    if (data.front.hasOwnProperty(n)) {
      sum = sum + (data.front[n].total || 0);
    }
  }
  return sum;
}

function fmtWallet() {
  var cash = data.wallet.cash;
  var pay = data.wallet.pay || 0;
  var total = cash - pay;
  var fOut = totalFrontOut();
  var lines = [];
  lines.push('WALLET');
  lines.push('────────────────');
  lines.push('cash       $' + cash);
  lines.push('pay        $' + pay);
  lines.push('total      $' + total);
  if (total > 0) {
    var hint = (total * 0.10);
    lines.push('(10% would be $' + hint.toFixed(2) + ')');
  }
  lines.push('');
  lines.push('\u26a0 front out  $' + fOut);
  return lines.join('\n');
}

function itemsToStr(arr) {
  var s = '';
  var k;
  for (k = 0; k < arr.length; k++) {
    if (k > 0) { s = s + ' '; }
    s = s + arr[k].qty + '\u00d7' + arr[k].product;
  }
  return s;
}

function priceLabel(v) {
  return (v === null || v === undefined) ? '[no price]' : '$' + v;
}

function htmlEsc(s) {
  if (s === null || s === undefined) { return ''; }
  return String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
}

function mapsLink(addr) {
  if (!addr) { return ''; }
  var fullAddr = addr;
  if (!/montreal|laval|brossard|quebec|qc/i.test(addr)) {
    fullAddr = addr + ', Montreal, QC, Canada';
  }
  return '<a href="https://www.google.com/maps/dir/?api=1&amp;destination=' + encodeURIComponent(fullAddr) + '">\ud83d\uddfa</a>';
}

function mapsUrlPlain(addr) {
  if (!addr) { return ''; }
  var full = addr;
  if (!/montreal|laval|brossard|quebec|qc/i.test(addr)) { full = addr + ', Montreal, QC, Canada'; }
  return 'https://maps.google.com/?q=' + encodeURIComponent(full);
}
function montrealMonDay(ts) {
  if (!ts) { return ''; }
  var __dp = montrealDateStr(ts).split('-');
  var __mn = ['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];
  return __mn[parseInt(__dp[1], 10) - 1] + ' ' + parseInt(__dp[2], 10);
}
var DRIVERS = ['T', 'FISTON'];
function driverBtn(token, label, sel) {
  return { text: (sel === label ? '🟢 ' + label : label), callback_data: 'setdrv:' + token + ':' + label };
}
function pendingMarkup(token, driver) {
  return { inline_keyboard: [
    [ driverBtn(token, 'T', driver), driverBtn(token, 'FISTON', driver) ],
    [ { text: '✅', callback_data: 'approve:' + token },
      { text: '🟧', callback_data: 'front_prompt:' + token },
      { text: '❌', callback_data: 'cancel:' + token } ]
  ] };
}
function pendingText(o) {
  var token = o.token || o.id;
  var L = [];
  L.push(token);
  L.push(o.name + '  ' + (o.price === null || o.price === undefined ? '[no price]' : '$' + o.price));
  L.push(itemsToStr(o.items));
  L.push((o.time || '[no time]') + '  ' + o.address);
  L.push('🗺 Maps: ' + mapsUrlPlain(o.address));
  L.push('Driver: ' + (o.driver || '—'));
  return L.join('\n');
}
function emitPending(o) {
  var token = o.token || o.id;
  var t = pendingText(o);
  return [{ json: {
    chat_id: chatId, text: t, is_callback: false, has_card: true, needs_parsing: false, token: token,
    telegram_body: { chat_id: chatId, text: t, reply_markup: pendingMarkup(token, o.driver || null) }
  } }];
}
function send(textOut) {
  return [{ json: { chat_id: chatId, text: textOut, is_callback: false, needs_parsing: false } }];
}

function sendHtmlText(htmlOut) {
  return [{ json: {
    chat_id: chatId,
    text: htmlOut,
    is_callback: false,
    has_card: true,
    needs_parsing: false,
    telegram_body: {
      chat_id: chatId,
      text: htmlOut,
      parse_mode: 'HTML'
    }
  } }];
}

function emitConfirmCard(cardText, callbackPrefix, actionToken) {
  return [{ json: {
    chat_id: chatId,
    text: cardText,
    is_callback: false,
    has_card: true,
    needs_parsing: false,
    token: actionToken,
    telegram_body: {
      chat_id: chatId,
      text: cardText,
      reply_markup: {
        inline_keyboard: [[
          { text: '\u2705', callback_data: callbackPrefix + ':' + actionToken },
          { text: '\u274c', callback_data: 'discard_action:' + actionToken }
        ]]
      }
    }
  } }];
}

// ===== 3b. UI KEYBOARD CONSTANTS + HELPERS (v7.5.0, v7.5.2) ==================

var REPLY_KEYBOARD = {
  keyboard: [
    [ { text: 'Wallet' },  { text: 'Jobs' },   { text: 'Front' } ],
    [ { text: 'Add' },     { text: 'Sub' },    { text: 'Paid' } ],
    [ { text: 'Summary' }, { text: 'Backup' }, { text: 'New Order' } ]
  ],
  resize_keyboard: true,
  is_persistent: true,
  selective: false
};

// Maps button labels -> what they do.
// 'direct'  = rewrite text to synthetic command, fall through to dispatch tables
// 'prompt'  = stage a prompt server-side, emit a plain question (v7.5.2)
var BUTTON_COMMANDS = {
  'Wallet':    { type: 'direct', cmd: 'c wallet' },
  'Jobs':      { type: 'direct', cmd: 'c jobs' },
  'Front':     { type: 'direct', cmd: 'c front' },
  'Summary':   { type: 'direct', cmd: 'c summary' },
  'Backup':    { type: 'direct', cmd: 'c backup' },
  'Add':       { type: 'prompt', prompt_type: 'wallet_add',  prompt_text: 'how much to add to cash?\n(reply with a number, or tap any other button to cancel)' },
  'Sub':       { type: 'prompt', prompt_type: 'wallet_sub',  prompt_text: 'how much to withdraw from cash?\n(reply with a number, or tap any other button to cancel)' },
  'Paid':      { type: 'prompt', prompt_type: 'wallet_paid', prompt_text: 'who paid? format: <name> [amount]\nexample: jay 100  (or just: jay for full)\n(or tap any other button to cancel)' },
  'New Order': { type: 'menu', menu: 'new_order' }
};

// Emit a plain text message with the reply keyboard attached. Used for `c kb`.
function emitWithKeyboard(textOut) {
  return [{ json: {
    chat_id: chatId,
    text: textOut,
    is_callback: false,
    has_card: true,
    needs_parsing: false,
    telegram_body: {
      chat_id: chatId,
      text: textOut,
      reply_markup: REPLY_KEYBOARD
    }
  } }];
}

// Inline two-mode New Order menu. Pure presentation; the operator's choice
// stages an intake prompt (handled in the callback handler).
function emitNewOrderMenu() {
  var menuText = [
    'NEW ORDER',
    '\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500',
    'pick an intake mode:',
    '',
    '\u2022 Free-form (one line):',
    '   maya 2 50p 65 10pm 4520 papineau',
    '',
    '\u2022 Form-style (multi-line):',
    '   maya',
    '   order: 2 50p',
    '   address: 4520 papineau',
    '   price: 65',
    '   time: 10pm   (blank = asap)'
  ].join('\n');
  return [{ json: {
    chat_id: chatId, text: menuText, is_callback: false, has_card: true, needs_parsing: false,
    telegram_body: { chat_id: chatId, text: menuText, reply_markup: { inline_keyboard: [[
      { text: 'Free-form',  callback_data: 'new_order:freeform' },
      { text: 'Form-style', callback_data: 'new_order:form' }
    ]] } }
  } }];
}

// v7.5.2: stage a prompt server-side and send a plain message (no force_reply).
// data.ui_prompts is keyed by chat_id so each chat can have at most one
// staged prompt at a time. Tapping a different prompt button replaces the
// previous staged prompt. The persistent reply keyboard stays attached so
// the user can tap any other button without going back to the typed command.
function stagePromptAndEmit(promptType, promptText) {
  data.ui_prompts[chatId] = {
    type: promptType,
    staged_at: nowTs,
    staged_by: userId
  };
  pushLog('ui_prompt_staged', { type: promptType });
  return [{ json: {
    chat_id: chatId,
    text: promptText,
    is_callback: false,
    has_card: true,
    needs_parsing: false,
    telegram_body: {
      chat_id: chatId,
      text: promptText,
      reply_markup: REPLY_KEYBOARD
    }
  } }];
}

// ===== 4. UI PROMPT RESOLUTION (v7.5.2) ======================================
// Runs BEFORE reply-to-bot handling because staged prompts don't depend on
// reply context. If a prompt is staged for this chat:
//   - text starts with 'c ' (any 'c'-prefixed command including button-rewrites)
//       → cancel the staged prompt, let the command run normally
//   - otherwise → treat the message as the answer to the staged prompt
//
// Stale prompts (>UI_PROMPT_TTL_SEC) auto-expire and behave as if not staged.

var stagedPrompt = data.ui_prompts[chatId];
if (stagedPrompt) {
  var stagedAge = nowTs - (stagedPrompt.staged_at || 0);
  if (stagedAge > UI_PROMPT_TTL_SEC) {
    // Expired. Drop it silently and continue.
    delete data.ui_prompts[chatId];
    pushLog('ui_prompt_expired', { type: stagedPrompt.type, age_sec: stagedAge });
    stagedPrompt = null;
  }
}

if (stagedPrompt) {
  // Detect button taps to other buttons (cancel + re-stage handled in 4b below
  // by the BUTTON_COMMANDS check). The cancel logic here covers typed commands
  // and direct-button rewrites that haven't happened yet.
  var __h = text.split(/\s+/)[0];
  var isCommand = text.indexOf('c ') === 0 || text === 'c' || COMMAND_HEADS.indexOf(__h) >= 0;
  var isDirectButtonTap = !!(BUTTON_COMMANDS[rawText] && BUTTON_COMMANDS[rawText].type === 'direct');
  var isPromptButtonTap = !!(BUTTON_COMMANDS[rawText] && BUTTON_COMMANDS[rawText].type === 'prompt');
  var isMenuButtonTap   = !!(BUTTON_COMMANDS[rawText] && BUTTON_COMMANDS[rawText].type === 'menu');

  if (isCommand || isDirectButtonTap || isPromptButtonTap || isMenuButtonTap) {
    // Cancel the staged prompt and let normal routing proceed.
    delete data.ui_prompts[chatId];
    pushLog('ui_prompt_cancelled', { type: stagedPrompt.type, reason: 'new_command' });
    // Do NOT return — fall through to button detection + dispatch.
  } else {
    // Treat this message as the answer to the staged prompt.
    var promptAnswer = (rawText || '').trim();
    var promptType = stagedPrompt.type;

    if (promptType === 'wallet_add') {
      var stAdd = parseInt(promptAnswer, 10);
      if (isNaN(stAdd) || stAdd <= 0) {
        // Bad input. Keep the prompt staged so they can retry without re-tapping.
        return send('bad amount. reply with a number, or tap any other button to cancel.');
      }
      delete data.ui_prompts[chatId];
      text = 'c wallet add ' + stAdd;
      rawText = text;
      // Fall through to dispatch with rewritten text.
    } else if (promptType === 'wallet_sub') {
      var stSub = parseInt(promptAnswer, 10);
      if (isNaN(stSub) || stSub <= 0) {
        return send('bad amount. reply with a number, or tap any other button to cancel.');
      }
      delete data.ui_prompts[chatId];
      text = 'c wallet sub ' + stSub;
      rawText = text;
    } else if (promptType === 'wallet_paid') {
      if (!promptAnswer) {
        return send('need a name. reply with <name> [amount], or tap any other button to cancel.');
      }
      delete data.ui_prompts[chatId];
      text = 'c wallet paid ' + promptAnswer.toLowerCase();
      rawText = text;
    } else if (promptType === 'new_order_freeform' || promptType === 'new_order_form') {
      // The message itself is the order text (either intake mode). Clear the
      // prompt and let normal intake (form parser / free-form) handle it.
      delete data.ui_prompts[chatId];
    } else {
      // Unknown staged type (shouldn't happen). Clear and route normally.
      delete data.ui_prompts[chatId];
    }
  }
}

// ===== 4b. REPLY-TO-BOT HANDLING (front prompt only, v7.5.2) =================
// The reply-to-bot path now ONLY handles data.front_prompts (the 🟧 long-press
// flow on order cards). The UI prompt path moved to section 4 above and no
// longer uses reply context — that's what v7.5.2 fixes.

if (msg.reply_to_message && msg.reply_to_message.from && msg.reply_to_message.from.is_bot) {
  var replyTargetId = msg.reply_to_message.message_id;

  if (data.front_prompts[replyTargetId]) {
    var fpRec = data.front_prompts[replyTargetId];
    var fpAmtRaw = (rawText || '').trim();
    var fpAmt = parseInt(fpAmtRaw, 10);
    if (!isNaN(fpAmt) && fpAmt > 0) {
      delete data.front_prompts[replyTargetId];
      text = 'c front ' + fpRec.order_id + ' ' + fpAmt;
      rawText = text;
    } else {
      delete data.front_prompts[replyTargetId];
      return [{ json: { chat_id: chatId, text: 'bad amount, front cancelled', is_callback: false, needs_parsing: false } }];
    }
  }
  // No `else suppress` branch anymore: if the reply isn't a front_prompt,
  // fall through to normal routing. iOS sticky-reply context where the
  // user types a regular command will now reach dispatch instead of being
  // silently swallowed (v7.5.1's bug).
}

// ----- front-reply fallback (dropped/mis-targeted reply context) -------------
// The 🟧 front prompt is the only feature still relying on Telegram reply
// context, which iOS frequently drops. When a front prompt is pending, a bare
// positive number is taken as the front amount (most recent prompt by ts) and
// routed into the existing `c front ord-N <amt>` path. Fires ONLY when a
// front_prompt exists, so no other parsing or flow is affected.
if (text.indexOf('c ') !== 0 && /^\d+$/.test((rawText || '').trim())
    && data.front_prompts && Object.keys(data.front_prompts).length > 0) {
  var __fpKeys = Object.keys(data.front_prompts);
  var __fpLatest = __fpKeys[0];
  var __fk;
  for (__fk = 1; __fk < __fpKeys.length; __fk++) {
    if ((data.front_prompts[__fpKeys[__fk]].ts || 0) > (data.front_prompts[__fpLatest].ts || 0)) { __fpLatest = __fpKeys[__fk]; }
  }
  var __fpRec2 = data.front_prompts[__fpLatest];
  var __fpAmt2 = parseInt((rawText || '').trim(), 10);
  delete data.front_prompts[__fpLatest];
  if (!isNaN(__fpAmt2) && __fpAmt2 > 0) {
    text = 'c front ' + __fpRec2.order_id + ' ' + __fpAmt2;
    rawText = text;
  } else {
    return [{ json: { chat_id: chatId, text: 'bad amount, front cancelled', is_callback: false, needs_parsing: false } }];
  }
}

// ===== 4c. UI BUTTON TAP DETECTION (v7.5.0, v7.5.2) ==========================
// Direct buttons rewrite `text` to a synthetic `c xxx` command and fall through
// to dispatch. Prompt buttons stage a server-side prompt (v7.5.2) and emit
// a plain question with the keyboard still attached.

if (BUTTON_COMMANDS[rawText]) {
  var btn = BUTTON_COMMANDS[rawText];
  if (btn.type === 'direct') {
    text = btn.cmd;
    rawText = text;
    // Fall through to dispatch tables below.
  } else if (btn.type === 'prompt') {
    return stagePromptAndEmit(btn.prompt_type, btn.prompt_text);
  } else if (btn.type === 'menu' && btn.menu === 'new_order') {
    return emitNewOrderMenu();
  }
}

// ===== 5. COMMAND HANDLERS ===================================================
// One function per command. Each returns the n8n output array directly.

// ----- claude toggle -----

function cmd_claudeOn() {
  data.claude_disabled = false;
  pushLog('claude_toggle', { state: 'on' });
  return send('claude parser ON\n(free-form messages will be parsed by claude)');
}
function cmd_claudeOff() {
  data.claude_disabled = true;
  pushLog('claude_toggle', { state: 'off' });
  return send('claude parser OFF\n(free-form messages will be rejected · use form template)');
}
function cmd_claudeStatus() {
  return send('claude parser: ' + (data.claude_disabled ? 'OFF' : 'ON'));
}

// ----- keyboard render (v7.5.0) -----

function cmd_kb() {
  pushLog('kb_render', {});
  return emitWithKeyboard('keyboard locked in. tap any button.');
}

// ----- ETA on-demand (v7.6.0) -----

async function cmd_eta(arg) {
  var address = (arg || '').toString().trim();
  if (!address) {
    return send('format: c eta <address>\nexample: c eta 7700 bd decarie');
  }

  var response;
  try {
    response = await httpRequest({
      method: 'POST',
      url: DISPATCH_ETA_URL,
      body: { address: address, auth: DISPATCH_SECRET },
      json: true,
      timeout: DISPATCH_TIMEOUT_MS
    });
  } catch (err) {
    pushLog('eta_call_failed', { address: address, error: String(err && err.message || err) });
    return send('eta request failed: dispatch unreachable\n(' + String(err && err.message || err).slice(0, 80) + ')');
  }

  if (!response || response.ok !== true) {
    var errMsg = (response && response.error) || 'unknown';
    pushLog('eta_call_rejected', { address: address, error: errMsg });
    if (errMsg === 'no location ping yet -- tap concierge ping on phone') {
      return send('\u26a0 no location ping yet\ntap "concierge ping" on phone to set location');
    }
    if (errMsg === 'no_route_found') {
      return send('\u26a0 no route found\ngoogle could not resolve that address');
    }
    if (errMsg === 'google_api_error') {
      return send('\u26a0 google api error\n(' + (response.google_status || 'unknown') + ')');
    }
    return send('\u26a0 eta failed: ' + errMsg);
  }

  var lines = [];
  lines.push('ETA  \u00b7  ' + htmlEsc(response.address_input));
  lines.push('\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500');
  lines.push('\ud83d\ude97 ' + response.eta_minutes + ' min  \u00b7  arrival ' + htmlEsc(response.arrival_label));
  // v7.5.3: client-facing buffered line (backward-compatible — only renders if dispatch v0.4.0+)
  if (response.client_eta_minutes !== undefined && response.client_arrival_label) {
    lines.push('   \u21b3 tell client: ' + response.client_eta_minutes + ' min \u00b7 ' + htmlEsc(response.client_arrival_label));
  }
