function cmd_walletPaid(arg) {
  var parts = arg.split(/\s+/);
  if (parts.length === 0 || !parts[0]) {
    return send('format: c wallet paid <name> [amount]');
  }
  var name = parts[0];
  if (!data.front[name] || !data.front[name].orders || data.front[name].orders.length === 0) {
    return send(name + ' has no outstanding fronts');
  }
  var currentTotal = data.front[name].total;
  var amount;
  if (parts.length === 1) {
    amount = currentTotal;
  } else {
    amount = parseInt(parts[1], 10);
    if (isNaN(amount) || amount <= 0) { return send('bad amount'); }
    if (amount > currentTotal) { return send(name + ' only owes $' + currentTotal); }
  }
  var actToken = 'act-' + data.next_action_id;
  data.next_action_id = data.next_action_id + 1;
  var remaining = amount;
  var allocPreview = [];
  var pf;
  for (pf = 0; pf < data.front[name].orders.length && remaining > 0; pf++) {
    var fEntry = data.front[name].orders[pf];
    var apply = remaining >= fEntry.amount ? fEntry.amount : remaining;
    allocPreview.push({ id: fEntry.id, before: fEntry.amount, after: fEntry.amount - apply });
    remaining = remaining - apply;
  }
  data.pending_actions[actToken] = {
    token: actToken, type: 'paid', target_name: name, amount: amount,
    allocation: allocPreview, staged_by: userId, staged_at: nowTs
  };
  var lines = [];
  if (amount === currentTotal) {
    lines.push('CONFIRM FULL PAYMENT');
    lines.push('────────────────');
    lines.push(name + '  ·  $' + amount + ' paid');
    lines.push('$' + currentTotal + ' \u2192 $0');
    lines.push('clears ' + allocPreview.length + ' front' + (allocPreview.length === 1 ? '' : 's'));
  } else {
    lines.push('CONFIRM PAYMENT');
    lines.push('────────────────');
    lines.push(name + '  ·  $' + amount + ' paid');
    lines.push('$' + currentTotal + ' \u2192 $' + (currentTotal - amount));
    var ap;
    for (ap = 0; ap < allocPreview.length; ap++) {
      var a = allocPreview[ap];
      if (a.before === a.after) continue;
      lines.push('  ' + a.id + ': $' + a.before + ' \u2192 $' + a.after);
    }
  }
  pushLog('paid_staged', { name: name, amount: amount, action_token: actToken });
  return emitConfirmCard(lines.join('\n'), 'apply_paid', actToken);
}

