// ----- undo / cancel / void -----

function cmd_undo() {
  if (!data.undo_buffer) { return send('nothing to undo'); }
  var ageSec = nowTs - data.undo_buffer.ts;
  if (ageSec > 300) {
    data.undo_buffer = null;
    return send('undo window expired (5min)');
  }
  if (data.undo_buffer.type === 'order_commit') {
    var ord = data.undo_buffer.order;
    data.orders = data.orders.filter(function(x) { return x.id !== ord.id; });
    var i;
    for (i = 0; i < ord.items.length; i++) {
      data.inventory[ord.items[i].product] = (data.inventory[ord.items[i].product] || 0) + ord.items[i].qty;
    }
    if (ord.price !== null && ord.price !== undefined) {
      data.wallet.cash = data.wallet.cash - ord.price;
    }
    data.wallet.pay = (data.wallet.pay || 0) - 20;
    if (data.wallet.pay < 0) { data.wallet.pay = 0; }
    if (data.clients[ord.name]) {
      var coIdx = data.clients[ord.name].orders.indexOf(ord.id);
      if (coIdx >= 0) { data.clients[ord.name].orders.splice(coIdx, 1); }
      if (ord.price !== null && ord.price !== undefined) {
        data.clients[ord.name].total_spent = (data.clients[ord.name].total_spent || 0) - ord.price;
        if (data.clients[ord.name].total_spent < 0) { data.clients[ord.name].total_spent = 0; }
      }
    }
    data.wallet.updated_at = nowTs;
    pushLog('undo_order', { id: ord.id });
    data.undo_buffer = null;
    return send('undone ' + ord.id);
  }
  return send('unknown undo type');
}

function cmd_cancel(arg) {
  var token = 'ord-' + arg;
  if (!data.pending[token]) {
    return send('order ' + token + ' not found in pending');
  }
  delete data.pending[token];
  pushLog('order_cancelled_cmd', { token: token });
  return send('cancelled ' + token);
}

function cmd_void(arg) {
  var token = 'ord-' + arg;
  var i;
  var idx = -1;
  for (i = 0; i < data.orders.length; i++) {
    if (data.orders[i].id === token) { idx = i; break; }
  }
  if (idx === -1) { return send('order ' + token + ' not found in jobs'); }
  var voidOrd = data.orders[idx];
  var actToken = 'act-' + data.next_action_id;
  data.next_action_id = data.next_action_id + 1;
  data.pending_actions[actToken] = {
    token: actToken, type: 'void', target_order_id: token,
    snapshot: voidOrd, staged_by: userId, staged_at: nowTs
  };
  var lines = [];
  lines.push('CONFIRM VOID  ·  ' + token);
  lines.push('────────────────');
  lines.push(voidOrd.name + '  ·  ' + priceLabel(voidOrd.price));
  lines.push(itemsToStr(voidOrd.items) + '  ·  ' + (voidOrd.time || '[no time]'));
  lines.push('Driver: ' + (voidOrd.driver || '—'));
  lines.push(voidOrd.address);
  if (voidOrd.front_amount && voidOrd.front_amount > 0) {
    lines.push('\u26a0 front $' + voidOrd.front_amount + ' will be reversed');
  }
  pushLog('void_staged', { token: token, action_token: actToken });
  return emitConfirmCard(lines.join('\n'), 'apply_void', actToken);
}

// ----- summary -----

function cmd_summary() {
  if (data.orders.length === 0 && data.voids.length === 0) {
    return send('no orders today');
  }
  var groups = {};
  var dayOrder = [];
  var totalRevenue = 0;
  var grandProductTally = {};
  var i, pi;
  for (i = 0; i < data.orders.length; i++) {
    var so = data.orders[i];
    var ts = so.approved_at || so.entered_at || nowTs;
    var ds = montrealDateStr(ts);
    if (!groups[ds]) { groups[ds] = []; dayOrder.push(ds); }
    groups[ds].push(so);
    if (so.price !== null && so.price !== undefined) { totalRevenue = totalRevenue + so.price; }
    for (pi = 0; pi < so.items.length; pi++) {
      var prodKey = so.items[pi].product;
      grandProductTally[prodKey] = (grandProductTally[prodKey] || 0) + so.items[pi].qty;
    }
  }
  dayOrder.sort();
  var multiDay = dayOrder.length > 1;
  var lines = [];
  if (multiDay) {
    lines.push('SUMMARY  ·  ' + montrealDatePretty(dayOrder[0]) + '  \u2192  ' + montrealDatePretty(dayOrder[dayOrder.length - 1]));
  } else if (dayOrder.length === 1) {
    lines.push('SUMMARY  ·  ' + montrealDatePretty(dayOrder[0]));
  } else {
    lines.push('SUMMARY  ·  ' + montrealDatePretty(montrealDateStr(nowTs)));
  }
  lines.push('════════════════');
  var di;
  for (di = 0; di < dayOrder.length; di++) {
    var ds2 = dayOrder[di];
    var orders = groups[ds2];
    if (multiDay) {
      lines.push('');
      lines.push('─── ' + montrealDatePretty(ds2) + ' ───');
    }
    var dayRev = 0;
    var dayTally = {};
    var oj;
    for (oj = 0; oj < orders.length; oj++) {
      var oo = orders[oj];
      var fTag2 = (oo.front_amount && oo.front_amount > 0) ? '  \u26a0 $' + oo.front_amount : '';
      lines.push(oo.id + ' · ' + oo.name + ' · ' + priceLabel(oo.price) + ' · ' + (oo.time || '[no time]') + ' · ' + itemsToStr(oo.items) + ' · ' + oo.address + ' · ' + (oo.driver || '\u2014') + fTag2);
      if (oo.price !== null && oo.price !== undefined) { dayRev = dayRev + oo.price; }
      var pj;
      for (pj = 0; pj < oo.items.length; pj++) {
        var dk = oo.items[pj].product;
        dayTally[dk] = (dayTally[dk] || 0) + oo.items[pj].qty;
      }
    }
    if (multiDay) {
      var dayTallyParts = [];
      var dtk;
      for (dtk in dayTally) {
        if (dayTally.hasOwnProperty(dtk)) {
          dayTallyParts.push(dayTally[dtk] + '\u00d7' + dtk);
        }
      }
      lines.push('day: ' + orders.length + ' job' + (orders.length === 1 ? '' : 's') + ' · $' + dayRev + (dayTallyParts.length > 0 ? ' · ' + dayTallyParts.join(' ') : ''));
    }
  }
  if (data.voids.length > 0) {
    lines.push('');
    lines.push('─── VOIDED ───');
    var vv;
    for (vv = 0; vv < data.voids.length; vv++) {
      var vo = data.voids[vv];
      lines.push(vo.id + ' · ' + vo.name + ' · ' + priceLabel(vo.price) + ' · ' + (vo.time || '[no time]') + ' · ' + itemsToStr(vo.items) + ' · ' + vo.address);
    }
  }
  lines.push('');
  lines.push('────────────────');
  var grandTallyParts = [];
  var gtk;
  for (gtk in grandProductTally) {
    if (grandProductTally.hasOwnProperty(gtk)) {
      grandTallyParts.push(grandProductTally[gtk] + '\u00d7' + gtk);
    }
  }
  var dayLabel = dayOrder.length + ' day' + (dayOrder.length === 1 ? '' : 's');
  lines.push(dayLabel + '  ·  ' + data.orders.length + ' job' + (data.orders.length === 1 ? '' : 's') + '  ·  $' + totalRevenue + (grandTallyParts.length > 0 ? '  ·  ' + grandTallyParts.join(' ') : ''));
  if (data.voids.length > 0) {
    lines.push(data.voids.length + ' voided');
  }
  return send(lines.join('\n'));
}

