// ----- front -----

function cmd_front() {
  var entries = [];
  var tn;
  for (tn in data.front) {
    if (data.front.hasOwnProperty(tn) && data.front[tn].orders) {
      var oj;
      for (oj = 0; oj < data.front[tn].orders.length; oj++) {
        if (data.front[tn].orders[oj].amount > 0) { entries.push({ name: tn, fe: data.front[tn].orders[oj] }); }
      }
    }
  }
  if (entries.length === 0) { return send('no open tabs'); }
  entries.sort(function (a, b) { return (a.fe.ts || 0) - (b.fe.ts || 0); });
  var lines = [];
  lines.push('OPEN TABS  ·  ' + entries.length);
  var grand = 0;
  var i;
  for (i = 0; i < entries.length; i++) {
    var nm = entries[i].name;
    var fe = entries[i].fe;
    var ord = null, oi;
    for (oi = 0; oi < data.orders.length; oi++) { if (data.orders[oi].id === fe.id) { ord = data.orders[oi]; break; } }
    if (!ord && data.pending && data.pending[fe.id]) { ord = data.pending[fe.id]; }
    if (!ord) { for (oi = 0; oi < data.voids.length; oi++) { if (data.voids[oi].id === fe.id) { ord = data.voids[oi]; break; } } }
    var dts = ord ? (ord.approved_at || ord.entered_at || fe.ts) : fe.ts;
    var seg = [nm, '$' + fe.amount, fe.id, montrealMonDay(dts)];
    if (ord && ord.items && ord.items.length) { seg.push(itemsToStr(ord.items)); }
    if (ord && ord.driver) { seg.push(ord.driver); }
    lines.push(seg.join('  ·  '));
    grand = grand + fe.amount;
  }
  lines.push('total owed: $' + grand);
  return send(lines.join('\n'));
}

function cmd_frontVoid(arg) {
  var parts = arg.split(/\s+/);
  if (parts.length < 2 || parts[1] === 'ord-') {
    return send('format: c front void <name> ord-N');
  }
  var name = parts[0];
  var ordId = parts[1];
  if (!data.front[name]) { return send(name + ' has no fronts'); }
  var idx = -1;
  var i;
  for (i = 0; i < data.front[name].orders.length; i++) {
    if (data.front[name].orders[i].id === ordId) { idx = i; break; }
  }
  if (idx === -1) { return send('no front for ' + ordId + ' under ' + name); }
  var amount = data.front[name].orders[idx].amount;
  var actToken = 'act-' + data.next_action_id;
  data.next_action_id = data.next_action_id + 1;
  data.pending_actions[actToken] = {
    token: actToken, type: 'forgive', target_name: name,
    target_order_id: ordId, amount: amount,
    staged_by: userId, staged_at: nowTs
  };
  var lines = [];
  lines.push('CONFIRM FORGIVE');
  lines.push('────────────────');
  lines.push(name + '  ·  ' + ordId + '  ·  $' + amount);
  lines.push('front out \u2192 $' + (data.front[name].total - amount) + ' (was $' + data.front[name].total + ')');
  lines.push('cash unchanged');
  pushLog('forgive_staged', { name: name, ord: ordId, amount: amount, action_token: actToken });
  return emitConfirmCard(lines.join('\n'), 'apply_forgive', actToken);
}

function cmd_frontOrd(arg) {
  var parts = arg.split(/\s+/);
  if (parts.length < 2) { return send('format: c front ord-N <amount>'); }
  var ordId = 'ord-' + parts[0];
  var amount = parseInt(parts[1], 10);
  if (isNaN(amount) || amount <= 0) { return send('bad amount'); }
  var isPending = !!data.pending[ordId];
  var approvedIdx = -1;
  var i;
  for (i = 0; i < data.orders.length; i++) {
    if (data.orders[i].id === ordId) { approvedIdx = i; break; }
  }
  var isApproved = approvedIdx >= 0;
  if (!isPending && !isApproved) { return send('order ' + ordId + ' not found'); }
  var target = isPending ? data.pending[ordId] : data.orders[approvedIdx];
  var price = target.price;
  if (price === null || price === undefined) { return send('cannot front order with no price'); }
  if (amount > price) { return send('front $' + amount + ' exceeds order price $' + price); }
  var actToken = 'act-' + data.next_action_id;
  data.next_action_id = data.next_action_id + 1;
  var existing = (target.front_amount || 0);
  data.pending_actions[actToken] = {
    token: actToken, type: 'front_set', target_order_id: ordId,
    target_status: isPending ? 'pending' : 'approved',
    target_name: target.name, new_front: amount, old_front: existing,
    order_price: price, staged_by: userId, staged_at: nowTs
  };
  var lines = [];
  lines.push('CONFIRM FRONT  ·  ' + ordId);
  lines.push('────────────────');
  lines.push(target.name + '  ·  $' + amount + ' of $' + price);
  if (existing > 0) { lines.push('was $' + existing + ' \u2192 $' + amount); }
  lines.push(isPending ? '(pending order)' : '(approved, retroactive)');
  pushLog('front_staged', { ord: ordId, amount: amount, action_token: actToken });
  return emitConfirmCard(lines.join('\n'), 'apply_front_set', actToken);
}

function cmd_frontName(arg) {
  var parts = arg.split(/\s+/);
  if (parts.length === 0 || !parts[0]) { return send('format: c front <name>'); }
  var name = parts[0];
  if (!data.front[name] || data.front[name].total === 0) { return send(name + ' has no open tab'); }
  var rec = data.front[name];
  var lines = [];
  lines.push(name.toUpperCase() + '  ·  OPEN TAB');
  var grand = 0;
  var i;
  for (i = 0; i < rec.orders.length; i++) {
    var fe = rec.orders[i];
    if (!(fe.amount > 0)) { continue; }
    var ord = null, oi;
    for (oi = 0; oi < data.orders.length; oi++) { if (data.orders[oi].id === fe.id) { ord = data.orders[oi]; break; } }
    if (!ord && data.pending && data.pending[fe.id]) { ord = data.pending[fe.id]; }
    if (!ord) { for (oi = 0; oi < data.voids.length; oi++) { if (data.voids[oi].id === fe.id) { ord = data.voids[oi]; break; } } }
    var dts = ord ? (ord.approved_at || ord.entered_at || fe.ts) : fe.ts;
    var seg = ['$' + fe.amount, fe.id, montrealMonDay(dts)];
    if (ord && ord.items && ord.items.length) { seg.push(itemsToStr(ord.items)); }
    if (ord && ord.address) { seg.push(ord.address); }
    if (ord && ord.driver) { seg.push(ord.driver); }
    lines.push(seg.join('  ·  '));
    grand = grand + fe.amount;
  }
  lines.push('total owed: $' + grand);
  return send(lines.join('\n'));
}

// ----- clients -----

function cmd_clients() {
  var names = Object.keys(data.clients);
  if (names.length === 0) { return send('no known clients'); }
  names.sort();
  var lines = [];
  lines.push('CLIENTS  ·  ' + names.length);
  lines.push('────────────────');
  var i;
  for (i = 0; i < names.length; i++) {
    var name = names[i];
    var rec = data.clients[name];
    var fOut = (data.front[name] && data.front[name].total) ? data.front[name].total : 0;
    var fTag = fOut > 0 ? '  ·  \u26a0 $' + fOut : '';
    lines.push(name + '  ·  ' + (rec.orders.length || 0) + ' orders  ·  $' + (rec.total_spent || 0) + ' lifetime' + fTag);
  }
  return send(lines.join('\n'));
}

function cmd_client(arg) {
  var parts = arg.split(/\s+/);
  var name = parts[0];
  var balanceOnly = (parts.length > 1 && parts[1] === 'balance');
  if (!data.clients[name]) { return send('client ' + name + ' not found'); }
  var rec = data.clients[name];
  var fRec = data.front[name];
  var fOut = (fRec && fRec.total) ? fRec.total : 0;
  var out = [];
  if (balanceOnly) {
    if (fOut === 0) { return send(name + ' has no outstanding fronts'); }
    out.push(name.toUpperCase() + '  ·  BALANCE');
    out.push('────────────────');
    var fbi;
    for (fbi = 0; fbi < fRec.orders.length; fbi++) {
      var fb = fRec.orders[fbi];
      var origPrice = null;
      var fboi;
      for (fboi = 0; fboi < data.orders.length; fboi++) {
        if (data.orders[fboi].id === fb.id) { origPrice = data.orders[fboi].price; break; }
      }
      if (origPrice === null) {
        for (fboi = 0; fboi < data.voids.length; fboi++) {
          if (data.voids[fboi].id === fb.id) { origPrice = data.voids[fboi].price; break; }
        }
      }
      if (origPrice !== null && fb.amount < origPrice) {
        out.push(fb.id + '  ·  $' + fb.amount + ' of $' + origPrice);
      } else {
        out.push(fb.id + '  ·  $' + fb.amount);
      }
    }
    out.push('────────────────');
    out.push('total: $' + fOut);
    return send(out.join('\n'));
  }
  out.push(name.toUpperCase());
  out.push('────────────────');
  out.push('lifetime orders: ' + (rec.orders ? rec.orders.length : 0));
  out.push('total spent: $' + (rec.total_spent || 0));
  out.push('currently owed: $' + fOut);
  if (fOut > 0) {
    out.push('');
    out.push('OUTSTANDING FRONTS');
    var oi;
    for (oi = 0; oi < fRec.orders.length; oi++) {
      var ofe = fRec.orders[oi];
      var ofePrice = null;
      var ofei;
      for (ofei = 0; ofei < data.orders.length; ofei++) {
        if (data.orders[ofei].id === ofe.id) { ofePrice = data.orders[ofei].price; break; }
      }
      if (ofePrice === null) {
        for (ofei = 0; ofei < data.voids.length; ofei++) {
          if (data.voids[ofei].id === ofe.id) { ofePrice = data.voids[ofei].price; break; }
        }
      }
      var paidOnThis = 0;
      if (ofe.paid_history && ofe.paid_history.length > 0) {
        var phi;
        for (phi = 0; phi < ofe.paid_history.length; phi++) { paidOnThis = paidOnThis + ofe.paid_history[phi].amount; }
      }
      if (paidOnThis > 0 && ofePrice !== null) {
        out.push(ofe.id + '  ·  $' + ofe.amount + ' of $' + ofePrice + ' (paid $' + paidOnThis + ')');
      } else if (ofePrice !== null && ofe.amount < ofePrice) {
        out.push(ofe.id + '  ·  $' + ofe.amount + ' of $' + ofePrice);
      } else {
        out.push(ofe.id + '  ·  $' + ofe.amount);
      }
    }
  }
  var clVoids = [];
  var cvi;
  for (cvi = 0; cvi < data.voids.length; cvi++) {
    if (data.voids[cvi].name === name) { clVoids.push(data.voids[cvi]); }
  }
  if (clVoids.length > 0) {
    out.push('');
    out.push('VOIDED  ·  ' + clVoids.length);
    var cvj;
    for (cvj = 0; cvj < clVoids.length; cvj++) {
      var cvo = clVoids[cvj];
      out.push(cvo.id + '  ·  ' + priceLabel(cvo.price) + '  ·  ' + (cvo.time || '[no time]'));
    }
  }
  return send(out.join('\n'));
}

