// ===== 6b. PREFIX-FREE NORMALIZATION (operator UX) ===========================
// Operator words work without the legacy 'c' prefix. We canonicalize a bare
// command ("wallet", "front 12 40", "new") to the existing 'c xxx' form so the
// dispatch tables below are unchanged. Legacy 'c xxx' still works during
// transition. Anything whose first word is not a known command is order intake.
(function () {
  var head = text.split(/\s+/)[0];
  var isLegacy = (text === 'c' || text.indexOf('c ') === 0);
  if (!isLegacy && COMMAND_HEADS.indexOf(head) >= 0) {
    text = 'c ' + text;
    rawText = 'c ' + rawText;
  }
})();

// ===== 7. DISPATCH ===========================================================

if (exactCommands[text]) {
  return exactCommands[text]();
}

var pc;
for (pc = 0; pc < prefixCommands.length; pc++) {
  var prefix = prefixCommands[pc][0];
  if (text.indexOf(prefix) === 0) {
    var arg = text.substring(prefix.length).trim();
    return prefixCommands[pc][1](arg);
  }
}

// ===== 8. FORM PARSER ========================================================

var rawLines = rawText.split('\n');
var firstLine = (rawLines[0] || '').trim().toLowerCase();
var firstLineParts = firstLine.split(/\s+/);
var formName = null;
if (firstLineParts[0] === 'c' && firstLineParts.length >= 2) { formName = firstLineParts[1]; }
else if (firstLineParts[0] && firstLineParts[0] !== 'c') { formName = firstLineParts[0]; }

var formOrderLine = null;
var formAddressLine = null;
var formTimeLine = null;
var formPriceLine = null;
var rli;
for (rli = 1; rli < rawLines.length; rli++) {
  var ln = rawLines[rli].trim();
  var orderMatch = ln.match(/^order\s*:\s*(.*)$/i);
  var addressMatch = ln.match(/^address\s*:\s*(.*)$/i);
  var timeMatch = ln.match(/^time\s*:\s*(.*)$/i);
  var priceMatch = ln.match(/^price\s*:\s*(.*)$/i);
  if (orderMatch) { formOrderLine = orderMatch[1].trim(); }
  else if (addressMatch) { formAddressLine = addressMatch[1].trim(); }
  else if (timeMatch) { formTimeLine = timeMatch[1].trim(); }
  else if (priceMatch) { formPriceLine = priceMatch[1].trim(); }
}

var isForm = (formName && formOrderLine !== null && formAddressLine !== null);

if (isForm) {
  var formOrderRaw = formOrderLine.toLowerCase().replace(/,/g, ' ');
  formOrderRaw = formOrderRaw.replace(/(\d+)([a-z])/g, '$1 $2');
  var itemTokens = formOrderRaw.split(/\s+/).filter(function(t){return t.length>0;});
  // re-merge half-products split by the (\d+)([a-z]) normalization above
  var __merged = [];
  for (var __mi = 0; __mi < itemTokens.length; __mi++) {
    if (itemTokens[__mi] === '50' && (itemTokens[__mi+1] === 'p' || itemTokens[__mi+1] === 'c' || itemTokens[__mi+1] === 'k')) {
      __merged.push('50' + itemTokens[__mi+1]); __mi++;
    } else { __merged.push(itemTokens[__mi]); }
  }
  itemTokens = __merged;
  var formItems = [];
  var iti = 0;
  while (iti < itemTokens.length) {
    var tok = itemTokens[iti];
    var qty = parseInt(tok, 10);
    if (!isNaN(qty) && iti + 1 < itemTokens.length && validProducts.indexOf(itemTokens[iti+1]) >= 0) {
      formItems.push({ qty: qty, product: itemTokens[iti+1] });
      iti = iti + 2;
    } else if (validProducts.indexOf(tok) >= 0) {
      formItems.push({ qty: 1, product: tok });
      iti = iti + 1;
    } else {
      iti = iti + 1;
    }
  }
  if (formItems.length === 0) {
    return send('form parse failed: no valid products in "order:" line\nvalid: c, 50c, p, 50p, b, k, 50k, m, s');
  }
  if (!formAddressLine) {
    return send('form parse failed: address line empty');
  }
  var formTime = (formTimeLine && formTimeLine.length > 0 && !/^[\[<].*[\]>]$/.test(formTimeLine)) ? formTimeLine : null;
  var formToken = 'ord-' + data.next_order_id;
  data.next_order_id = data.next_order_id + 1;
  var formPending = {
    token: formToken,
    name: formName.toLowerCase(),
    items: formItems,
    price: (formPriceLine && !isNaN(parseInt(formPriceLine, 10))) ? parseInt(formPriceLine, 10) : null,
    time: formTime,
    address: formAddressLine.toLowerCase(),
    entered_by: userId,
    entered_at: nowTs,
    front_amount: 0
  };
  data.pending[formToken] = formPending;
  pushLog('order_pending_form', { token: formToken, raw: rawText });
  formPending.driver = null;
  return emitPending(formPending);
}

// ===== 9. FALL-THROUGH =======================================================

if (data.claude_disabled) {
  return send('claude parser is OFF\nuse form template:\n\nc <name>\norder: <items>\naddress: <street>\ntime: <optional>\n\nor: c claude on');
}

var __claudeText = rawText;
if (__claudeText.toLowerCase().indexOf('c ') === 0) { __claudeText = __claudeText.slice(2); }
return [{
