var data = $getWorkflowStaticData('global');
if (!data.pending) { data.pending = {}; }
if (!data.pending_edits) { data.pending_edits = {}; }
if (!data.next_order_id) { data.next_order_id = 1; }
if (!data.log) { data.log = []; }

var upstream = $('Needs Parsing?').item.json;
var chatId = upstream.chat_id;
var userId = upstream.user_id;
var rawText = upstream.raw_text;
var isEdit = upstream.is_edit === true;
var editTarget = upstream.edit_target || 'none';
var editToken = upstream.edit_token || null;
var nowTs = Math.floor(Date.now() / 1000);

var apiResponse = $json;
var parsedJson = null;
var parseError = null;

try {
  if (apiResponse.content && apiResponse.content.length > 0) {
    var rawReply = apiResponse.content[0].text || '';
    rawReply = rawReply.replace(/```json/g, '').replace(/```/g, '').trim();
    parsedJson = JSON.parse(rawReply);
