  };
  if (parsedJson.name !== null && parsedJson.name !== undefined) { after.name = parsedJson.name; }
  if (parsedJson.items !== null && parsedJson.items !== undefined && parsedJson.items.length > 0) { after.items = parsedJson.items; }
  if (parsedJson.price !== null && parsedJson.price !== undefined) { after.price = parsedJson.price; }
  if (parsedJson.time !== null && parsedJson.time !== undefined) { after.time = parsedJson.time; }
  if (parsedJson.address !== null && parsedJson.address !== undefined) { after.address = parsedJson.address; }

  data.pending_edits[editToken] = {
    token: editToken, before: before, after: after,
    staged_by: userId, staged_at: nowTs
  };
  data.log.push({ ts: nowTs, by: userId, action: 'order_edit_staged', details: { token: editToken, raw: rawText } });
  if (data.log.length > 500) { data.log = data.log.slice(data.log.length - 500); }

  var nameLine = before.name === after.name ? before.name : (before.name + ' \u2192 ' + after.name);
  var priceBefore = priceLabel(before.price);
  var priceAfter = priceLabel(after.price);
  var priceLine = priceBefore === priceAfter ? priceAfter : (priceBefore + ' \u2192 ' + priceAfter);
  var itemsBefore = itemsToStr(before.items);
  var itemsAfter = itemsToStr(after.items);
  var itemsLine = itemsBefore === itemsAfter ? itemsAfter : (itemsBefore + ' \u2192 ' + itemsAfter);
  var timeBefore = timeLabel(before.time);
