  }
  token = editToken;
  pending = data.pending[editToken];
  if (parsedJson.name !== null && parsedJson.name !== undefined) { pending.name = parsedJson.name; }
  if (parsedJson.items !== null && parsedJson.items !== undefined && parsedJson.items.length > 0) { pending.items = parsedJson.items; }
  if (parsedJson.price !== null && parsedJson.price !== undefined) { pending.price = parsedJson.price; }
  if (parsedJson.time !== null && parsedJson.time !== undefined) { pending.time = parsedJson.time; }
