      vlines.push(itemsToStr2(voidedOrder.items));
      vlines.push((voidedOrder.time || '[no time]') + '  ' + voidedOrder.address);
      if (voidWasFronted) { vlines.push('\u26a0 front $' + voidFrontAmt + ' reversed'); }
      responseText = vlines.join('\n');
      auditAction = 'order_voided';
    }
  }
} else if (action === 'apply_reset_soft') {
  var softAct = data.pending_actions[token];
  if (!softAct || softAct.type !== 'reset_soft') {
    responseText = 'reset action ' + token + ' not found or already handled.';
    auditAction = 'callback_stale_reset';
  } else {
    var clearedCount = data.orders.length;
    data.orders = [];
    delete data.pending_actions[token];
    responseText = 'jobs reset \u2014 ' + clearedCount + ' cleared. wallet + inventory + pending + clients + front kept.';
    auditAction = 'jobs_reset_soft';
  }
} else if (action === 'apply_reset_hard') {
  var hardAct = data.pending_actions[token];
  if (!hardAct || hardAct.type !== 'reset_hard') {
    responseText = 'reset action ' + token + ' not found or already handled.';
    auditAction = 'callback_stale_reset';
  } else {
    var hClearedOrders = data.orders.length;
    var hClearedPending = Object.keys(data.pending).length;
    var hClearedEdits = Object.keys(data.pending_edits).length;
    data.orders = [];
    data.voids = [];
    data.pending = {};
    data.pending_edits = {};
    data.undo_buffer = null;
    data.next_order_id = 1;
    delete data.pending_actions[token];
    responseText = 'HARD reset \u2014 ' + hClearedOrders + ' orders, ' + hClearedPending + ' pending, ' + hClearedEdits + ' edits cleared. ord-N \u2192 1. wallet + inventory + clients + front kept.';
    auditAction = 'jobs_reset_hard';
  }
} else if (action === 'apply_front_set') {
  var frAct = data.pending_actions[token];
  if (!frAct || frAct.type !== 'front_set') {
    responseText = 'front action ' + token + ' not found or already handled.';
    auditAction = 'callback_stale_front';
  } else {
    var frOrdId = frAct.target_order_id;
    var frTargetStatus = frAct.target_status;
    var frName = frAct.target_name;
    var frNewAmt = frAct.new_front;
    var frOldAmt = frAct.old_front;
    var frDelta = frNewAmt - frOldAmt;
    if (frTargetStatus === 'pending') {
      if (data.pending[frOrdId]) {
        data.pending[frOrdId].front_amount = frNewAmt;
      } else {
        var farIdx = -1;
        var fari;
        for (fari = 0; fari < data.orders.length; fari++) {
          if (data.orders[fari].id === frOrdId) { farIdx = fari; break; }
        }
        if (farIdx >= 0) { data.orders[farIdx].front_amount = frNewAmt; }
      }
    } else {
      var farIdx2 = -1;
      var fari2;
      for (fari2 = 0; fari2 < data.orders.length; fari2++) {
        if (data.orders[fari2].id === frOrdId) { farIdx2 = fari2; break; }
      }
      if (farIdx2 >= 0) { data.orders[farIdx2].front_amount = frNewAmt; }
    }
    ensureFront(frName);
    var frEntryIdx = -1;
    var frei;
    for (frei = 0; frei < data.front[frName].orders.length; frei++) {
      if (data.front[frName].orders[frei].id === frOrdId) { frEntryIdx = frei; break; }
    }
    if (frEntryIdx === -1 && frNewAmt > 0) {
      data.front[frName].orders.push({ id: frOrdId, amount: frNewAmt, ts: nowTs, paid_history: [] });
    } else if (frEntryIdx >= 0) {
      if (frNewAmt === 0) {
        data.front[frName].orders.splice(frEntryIdx, 1);
      } else {
        data.front[frName].orders[frEntryIdx].amount = frNewAmt;
      }
    }
    data.front[frName].total = data.front[frName].total + frDelta;
    if (data.front[frName].total < 0) { data.front[frName].total = 0; }
    if (data.clients[frName]) {
      data.clients[frName].total_spent = (data.clients[frName].total_spent || 0) - frDelta;
      if (data.clients[frName].total_spent < 0) { data.clients[frName].total_spent = 0; }
    }
    delete data.pending_actions[token];
    var frRespLines = [];
    frRespLines.push('\u26a0 ' + frOrdId + ' fronted $' + frNewAmt);
    frRespLines.push(frName + '  front out: $' + data.front[frName].total);
    responseText = frRespLines.join('\n');
    auditAction = 'front_applied';
  }
} else if (action === 'apply_paid') {
  var paidAct = data.pending_actions[token];
  if (!paidAct || paidAct.type !== 'paid') {
    responseText = 'paid action ' + token + ' not found or already handled.';
    auditAction = 'callback_stale_paid';
  } else {
    var pdName = paidAct.target_name;
    var pdAmount = paidAct.amount;
    if (!data.front[pdName]) {
      delete data.pending_actions[token];
      responseText = pdName + ' has no fronts (changed since stage)';
      auditAction = 'apply_paid_stale';
    } else {
      var pdRemaining = pdAmount;
      var pdi = 0;
      while (pdRemaining > 0 && pdi < data.front[pdName].orders.length) {
        var pdEntry = data.front[pdName].orders[pdi];
        var pdApply = pdRemaining >= pdEntry.amount ? pdEntry.amount : pdRemaining;
        if (!pdEntry.paid_history) { pdEntry.paid_history = []; }
        pdEntry.paid_history.push({ amount: pdApply, ts: nowTs });
        pdEntry.amount = pdEntry.amount - pdApply;
        pdRemaining = pdRemaining - pdApply;
        if (pdEntry.amount === 0) {
          var pdOrdIdx = -1;
          var pdoi;
          for (pdoi = 0; pdoi < data.orders.length; pdoi++) {
            if (data.orders[pdoi].id === pdEntry.id) { pdOrdIdx = pdoi; break; }
          }
          if (pdOrdIdx >= 0) { data.orders[pdOrdIdx].front_amount = 0; }
          data.front[pdName].orders.splice(pdi, 1);
        } else {
          var pdOrdIdxP = -1;
          var pdoiP;
          for (pdoiP = 0; pdoiP < data.orders.length; pdoiP++) {
            if (data.orders[pdoiP].id === pdEntry.id) { pdOrdIdxP = pdoiP; break; }
          }
          if (pdOrdIdxP >= 0) { data.orders[pdOrdIdxP].front_amount = pdEntry.amount; }
          pdi = pdi + 1;
        }
      }
      data.front[pdName].total = data.front[pdName].total - (pdAmount - pdRemaining);
      if (data.front[pdName].total < 0) { data.front[pdName].total = 0; }
      if (data.clients[pdName]) {
        data.clients[pdName].total_spent = (data.clients[pdName].total_spent || 0) + (pdAmount - pdRemaining);
        data.clients[pdName].last_seen = nowTs;
      }
      delete data.pending_actions[token];
      var pdRespLines = [];
      pdRespLines.push(pdName + ' paid $' + (pdAmount - pdRemaining));
      pdRespLines.push('front out: $' + data.front[pdName].total);
      responseText = pdRespLines.join('\n');
      auditAction = 'paid_applied';
    }
  }
} else if (action === 'apply_forgive') {
  var fgAct = data.pending_actions[token];
  if (!fgAct || fgAct.type !== 'forgive') {
    responseText = 'forgive action ' + token + ' not found or already handled.';
    auditAction = 'callback_stale_forgive';
  } else {
    var fgName = fgAct.target_name;
    var fgOrdId = fgAct.target_order_id;
    var fgAmount = fgAct.amount;
    if (!data.front[fgName]) {
      delete data.pending_actions[token];
      responseText = fgName + ' has no fronts (changed since stage)';
      auditAction = 'apply_forgive_stale';
    } else {
      var fgIdx = -1;
      var fgi;
      for (fgi = 0; fgi < data.front[fgName].orders.length; fgi++) {
        if (data.front[fgName].orders[fgi].id === fgOrdId) { fgIdx = fgi; break; }
      }
      if (fgIdx === -1) {
        delete data.pending_actions[token];
        responseText = 'no front for ' + fgOrdId + ' (changed since stage)';
        auditAction = 'apply_forgive_stale';
      } else {
        var fgEntry = data.front[fgName].orders[fgIdx];
        data.front[fgName].total = data.front[fgName].total - fgEntry.amount;
        if (data.front[fgName].total < 0) { data.front[fgName].total = 0; }
        data.front[fgName].orders.splice(fgIdx, 1);
        var fgOrdIdx = -1;
        var fgoi;
        for (fgoi = 0; fgoi < data.orders.length; fgoi++) {
          if (data.orders[fgoi].id === fgOrdId) { fgOrdIdx = fgoi; break; }
        }
        if (fgOrdIdx >= 0) {
          data.orders[fgOrdIdx].forgiven = true;
          data.orders[fgOrdIdx].forgiven_by = userId;
          data.orders[fgOrdIdx].forgiven_at = nowTs;
          data.orders[fgOrdIdx].front_amount = 0;
        }
        delete data.pending_actions[token];
        var fgLines = [];
        fgLines.push('forgiven ' + fgOrdId);
        fgLines.push(fgName + '  $' + fgEntry.amount + ' forgiven');
        fgLines.push('front out: $' + data.front[fgName].total);
        responseText = fgLines.join('\n');
        auditAction = 'front_forgiven';
      }
    }
  }
} else if (action === 'new_order') {
  // token is 'freeform' or 'form'. Stage an intake prompt so the operator's
  // next message is treated as the order text in the chosen mode.
  if (!data.ui_prompts) { data.ui_prompts = {}; }
  data.ui_prompts[chatId] = { type: 'new_order_' + token, staged_at: nowTs, staged_by: userId };
  responseText = (token === 'form')
    ? 'form-style: send\nname\norder: ...\naddress: ...\nprice: ...\ntime: ... (blank=asap)'
    : 'free-form: send one line\nexample: maya 2 50p 65 10pm 4520 papineau';
  auditAction = 'new_order_prompt';
} else if (action === 'purge_next') {
  var pgA = data.pending_actions[token];
  if (!pgA || pgA.type !== 'purge') {
    responseText = 'purge ' + token + ' not found or already handled.';
    auditAction = 'callback_stale_action';
  } else {
    pgA.stage = 2;
    var pgLabel = pgA.area === 'inv' ? 'INVENTORY' : (pgA.area === 'front' ? 'FRONT' : 'WALLET');
    var pgNoun = pgA.area === 'inv' ? 'inventory' : pgA.area;
    responseText = 'PURGE ' + pgLabel + '\nstep 1 confirmed — final confirm below.';
    confirmCardText = ['FINAL CONFIRM · PURGE ' + pgLabel,
      'You are about to erase ' + pgNoun + ' data from SB.',
      'No undo.', 'Step 2 of 2.'].join('\n');
    confirmCardMarkup = { inline_keyboard: [[
      { text: '✅', callback_data: 'purge_apply:' + token },
      { text: '❌', callback_data: 'discard_action:' + token }
    ]] };
    auditAction = 'purge_step2';
  }
} else if (action === 'purge_apply') {
  var pgB = data.pending_actions[token];
  if (!pgB || pgB.type !== 'purge' || pgB.stage !== 2) {
    responseText = 'purge ' + token + ' not found or not confirmed.';
    auditAction = 'callback_stale_action';
  } else {
    if (pgB.area === 'wallet') {
      data.wallet = { cash: 0, pay: 0, updated_at: nowTs };
      responseText = '✅ wallet data erased from SB (active period)';
      auditAction = 'purge_wallet_applied';
    } else if (pgB.area === 'inv') {
      data.inventory = { c:0, '50c':0, p:0, '50p':0, b:0, '50k':0, k:0, m:0, s:0 };
      responseText = '✅ inventory data erased from SB (active period)';
      auditAction = 'purge_inv_applied';
    } else if (pgB.area === 'front') {
      data.front = {};
      var pgi;
      for (pgi = 0; pgi < data.orders.length; pgi++) { data.orders[pgi].front_amount = 0; }
      var pgk;
      for (pgk in data.pending) { if (data.pending.hasOwnProperty(pgk)) { data.pending[pgk].front_amount = 0; } }
      responseText = '✅ front data erased from SB (active period)';
      auditAction = 'purge_front_applied';
    } else {
      responseText = 'unknown purge area';
      auditAction = 'callback_unknown';
    }
    delete data.pending_actions[token];
  }
} else if (action === 'setdrv') {
  var drvSel = parts[2];
  if (!data.pending[token]) {
    responseText = 'Order ' + token + ' not found or already handled.';
    auditAction = 'callback_stale';
  } else if (drvSel !== 'T' && drvSel !== 'FISTON') {
    auditAction = 'driver_invalid';
  } else {
    data.pending[token].driver = drvSel;
    editMarkupText = pendingText2(data.pending[token]);
    editMarkup = pendingMarkup2(token, drvSel);
    auditAction = 'driver_selected';
  }
} else if (action === 'discard_action') {
  if (!data.pending_actions[token]) {
    responseText = 'action ' + token + ' not found or already handled.';
    auditAction = 'callback_stale_action';
  } else {
    var discardedType = data.pending_actions[token].type;
    delete data.pending_actions[token];
    responseText = discardedType + ' discarded';
    auditAction = 'action_discarded';
  }
} else if (action === 'copy_snippet') {
  // v7.6.3: copy-for-client button on auto-ETA card. `token` is the snip-N ID.
  var snipRec = data.eta_snippets[token];
  if (!snipRec) {
    // Snippet was pruned (>24h old or >100 newer snippets created since).
    // Don't error noisily; just ack the callback silently.
    responseText = 'snippet expired';
    auditAction = 'copy_snippet_stale';
  } else {
    snippetMessageText = snipRec.text;
    // Mark consumed but don't delete — Steven may tap copy twice if he fumbles
    // the long-press. Snippet ages out via the 100-cap or 24h prune.
    snipRec.last_tapped_at = nowTs;
    responseText = ''; // empty: don't change the original card text
    auditAction = 'copy_snippet_emitted';
  }
} else {
  responseText = 'unknown action: ' + action;
  auditAction = 'callback_unknown';
}

data.log.push({ ts: nowTs, by: userId, action: auditAction, details: { token: token, action: action } });
if (data.log.length > 500) { data.log = data.log.slice(data.log.length - 500); }

// AUTO-ETA: if commit succeeded and order is ASAP (no reservation time), fetch ETA.
var etaCardText = null;
var etaCardSnipId = null; // v7.6.3: snippet ID for the [copy for client] callback
if (autoEtaOrder) {
  var eta = await fetchAutoEta(autoEtaOrder);
  if (eta && !eta._failed) {
    var cardData = buildEtaCardData(autoEtaOrder, eta);
    if (cardData) {
      etaCardText = cardData.text;
      if (cardData.snippet) {
        etaCardSnipId = stageSnippet(cardData.snippet);
      }
    }
    data.log.push({ ts: nowTs, by: userId, action: 'auto_eta_success', details: { token: autoEtaOrder.id, eta_min: eta.eta_minutes } });
  } else if (eta && eta._failed) {
    data.log.push({ ts: nowTs, by: userId, action: 'auto_eta_failed', details: { token: autoEtaOrder.id, reason: eta._reason } });
  }
  if (data.log.length > 500) { data.log = data.log.slice(data.log.length - 500); }
}

return [{
  json: {
    chat_id: chatId, message_id: msgId, callback_query_id: cbId,
    text: responseText, is_callback: true,
    eta_card_text: etaCardText,
    eta_card_snip_id: etaCardSnipId,         // v7.6.3: drives copy-button on auto-ETA card
    snippet_message_text: snippetMessageText, // v7.6.3: drives Send Snippet HTTP node
    confirm_card_text: confirmCardText,        // purge: drives Has Confirm Card? / Send Confirm Card HTTP
    confirm_card_markup: confirmCardMarkup,
    edit_markup_text: editMarkupText,   // driver: drives Has Edit Markup? / Edit Card With Buttons HTTP
    edit_markup: editMarkup
  }
}];

parameters.jsonBody:
={{ JSON.stringify({
  chat_id: $('Callback Handler').item.json.chat_id,
  text: $('Callback Handler').item.json.eta_card_text,
  parse_mode: "HTML",
  ...$('Callback Handler').item.json.eta_card_snip_id ? {
    reply_markup: {
      inline_keyboard: [[
        { text: "📋 copy for client", callback_data: "copy_snippet:" + $('Callback Handler').item.json.eta_card_snip_id }
      ]]
    }
  } : {}
}) }}
